local guideComp            = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)

local ParseStringByLevel = GuideUtils.ParseStringByLevel
local SplitFlagLevel     = GuideUtils.SplitFlagLevel

local CustomEventConf = {
    ["AllMainUI"]                           = function (exParams)
        return checkNumber(exParams) == 1
    end,
    ["MaidCoff.SetRoleControllerShowState"] = function (exParams)
        return checkNumber(exParams) == 1
    end,
}

local FixPathIndex = function(path, index)
    if string.isEmpty(path) then
        return path
    end
    local splitFlag1 = GuideUtils.GetSplitFlag(SplitFlagLevel.Level1)
    local splitFlag2 = GuideUtils.GetSplitFlag(SplitFlagLevel.Level2)
    local splitFlag3 = GuideUtils.GetSplitFlag(SplitFlagLevel.Level3)
    local nodeInfoList = ParseStringByLevel(SplitFlagLevel.Level1, path) 
    for i, nodeInfoStr in ipairs(nodeInfoList) do
        local nodeInfoParamsList = ParseStringByLevel(SplitFlagLevel.Level2, nodeInfoStr)
        local _, paramsStr = SafeUnpack(nodeInfoParamsList)
        local paramsList      = ParseStringByLevel(SplitFlagLevel.Level3, paramsStr)
        paramsList[2]         = index
        nodeInfoParamsList[2] = table.concat(paramsList, splitFlag3)
        nodeInfoList[i]       = table.concat(nodeInfoParamsList, splitFlag2)
    end

    return table.concat(nodeInfoList, splitFlag1)
end
