---Execute
---@param moduleStepVo SystemGuideModuleStepVo
---@param context UISystemGuideDialog
function UISystemGuidePreBehavior:Execute(moduleStepVo, context)
    local guidePreBehavior = moduleStepVo.guidePreBehavior
    if string.isEmpty(guidePreBehavior) then return end
    local guidePreBehaviorGroups = ParseStringByLevel(SplitFlagLevel.Level1, guidePreBehavior)
    self._guidePreBehaviorGroups = guidePreBehaviorGroups
    for i, guidePreBehaviorGroup in ipairs(guidePreBehaviorGroups) do
        local preBehaviorType, preBehaviorTypeParams, exParams, exParams1, exParams2 = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level2, guidePreBehaviorGroup))
        self:ShowGuidePreBehavior(preBehaviorType, preBehaviorTypeParams, exParams, exParams1, exParams2, moduleStepVo, context)
    end
end

