---HandleTypeFixCultivateListIndex
---处理类型 战斗选择  替换 eventInfo 与 actionInfo 再中设置节点下标
---@param viewType CardProgressionConstants.MainViewType
---@param moduleStepVo SystemGuideModuleStepVo
function UISystemGuidePreBehavior:HandleTypeFixCultivateListIndex(viewType, moduleStepVo)
    viewType = checkNumber(viewType)
    if viewType <= 0 then
        return
    end

    --- 1. 获取养成主界面
    ---@type CardProgressionMainDialog
    local Env = self:GetCurDialogEnv()

    --- 2. 通过viewType 获取tab Index
    local index = Env:GetTabIndexByViewType(viewType)
    if index == nil or index < 1 then
        return
    end

    --- 3. fix moduleStepVo.eventInfo moduleStepVo.actionInfo
    index = index - 1

    local eventInfo = moduleStepVo.eventInfo
    moduleStepVo.eventInfo  = FixPathIndex(eventInfo, index)
    local actionInfo = moduleStepVo.actionInfo
    moduleStepVo.actionInfo = FixPathIndex(actionInfo, index)

    printInfo("guide---------------->>>> fix eventInfo %s -> %s", eventInfo, moduleStepVo.eventInfo)
    printInfo("guide---------------->>>> fix actionInfo %s -> %s", actionInfo, moduleStepVo.actionInfo)
    
end

