---HandleTypeCustomEvent
---发送自定义事件
---@param preBehaviorTypeParams string 事件名称
function UISystemGuidePreBehavior:HandleTypeCustomEvent(preBehaviorTypeParams, exParams, isInverter)
    if string.isEmpty(preBehaviorTypeParams) then
        return
    end
    
    local func = CustomEventConf[preBehaviorTypeParams]
    local res
    if func ~= nil then
        res = func(exParams)
        if isInverter and type(res) == "boolean" then
            res = not res
        end
    end
    Events.Broadcast(preBehaviorTypeParams, res)
    
end

