function UISystemGuidePreBehavior:HandleTypeSetRenderSortingOrder(preBehaviorTypeParams)
    local OrderTrackerType = typeof(CS.Engine.UI.OrderTracker)
    local guideGo = guideComp:GetGuideGo()
    ---@type Engine.UI.OrderTracker
    local orderTracker = KTool.GetOrAddComponent(guideGo.gameObject, OrderTrackerType)
    local sortingOrder = orderTracker.addSortingOrder

    local isSecondPop   = string.find(preBehaviorTypeParams, "UIRoot")
    local nodeType = isSecondPop and 1 or 0
    local node     = GuideUtils.GetNode(preBehaviorTypeParams, nodeType)
    if isNull(node) then
        return
    end
    if isSecondPop then
        ---@type UnityEngine.Canvas
       local canvas = KTool.GetComponent(node.gameObject, CanvasType) 
       if isNotNull(canvas) then
            local mainCanvas = CS.Engine.UI.UIRootCanvas.main.canvas
            canvas.renderMode = mainCanvas.renderMode
            canvas.worldCamera = mainCanvas.worldCamera
            canvas.gameObject.layer = mainCanvas.gameObject.layer
       end
    end
    orderTracker = KTool.GetOrAddComponent(node.gameObject, OrderTrackerType)
    orderTracker.addSortingOrder = sortingOrder - 1
    yield_return()

end

function UISystemGuidePreBehavior:HandleTypeLoadFile(preBehaviorTypeParams)
    ---@type UISystemGuideDialog
    local context = self.context
    local path    = preBehaviorTypeParams
    local name    = string.stripExtension(string.stripFileName(path))
    
    if not isNull(context:GetLoader(name)) then return end
    
    local loader = ResourceModule.LoadBundleAsync(path, nil, true)
    context:RegLoader(name, loader)
    
end

