function UISystemGuidePreBehavior:HandleTypeSetEnabledComponent(typeFullName, isEnable, nodePath, nodeType, isInverter)
    local node = GuideUtils.GetNode(nodePath, checkNumber(nodeType))
    --- 真机会出现 类型还没初始化的问题 这里需要等类型初始
    local isFind = false
    local go = node.gameObject
    
    while not isFind do
        local components = go:GetComponents(typeof(CS.UnityEngine.Component))
        for i = 1, components.Length do
            ---@type UnityEngine.Component
            local component = components[i-1]
            local type = component:GetType()
            if type.FullName == typeFullName then
                local res = checkNumber(isEnable) == 1
                if isInverter then
                    res = not res
                end
                component.enabled = res
                isFind = true

                ---由于引导屏蔽层 挡不住 CommonTipsBoard 这里在 BehaviourAction.enabled = false 后 强发下关闭标识
                if typeFullName == "Engine.Lib.BehaviourAction" then
                    -- Events.Broadcast("CloseTipsBoardGuideFlag", false)
                end
                return
            end
        end
        yield_return()
    end
    
    
end

function UISystemGuidePreBehavior:HandleTypeWaitNodeShow(nodePath, nodeType)
    local node = GuideUtils.GetNode(nodePath, checkNumber(nodeType))
    local gameObject = node.gameObject
    local seconds = Yielders.GetWaitForSeconds(0.2)
    while not KTool.IsActiveInHierarchy(gameObject) do
        yield_return(seconds)
    end
end

function UISystemGuidePreBehavior:HandleTypeFixEditTeamListIndex(moduleStepVo)
    ---@type UIFightTeamDialog
    local Env = self:GetCurDialogEnv()
    if isNull(Env) then
        return
    end
    local index = Env:GetPlayerCardIndex()
    if index == nil or index <= 1 then
        return
    end
    -- index = index
    -- print("index", index)
    local function Replace(path)
        return string.gsub(path, "TeamNode1", string.format("TeamNode%s", index))
    end

    local eventInfo = moduleStepVo.eventInfo
    moduleStepVo.eventInfo  = Replace(eventInfo)
    local actionInfo = moduleStepVo.actionInfo
    moduleStepVo.actionInfo = Replace(actionInfo)

    printInfo("guide---------------->>>> fix eventInfo %s -> %s", eventInfo, moduleStepVo.eventInfo)
    printInfo("guide---------------->>>> fix actionInfo %s -> %s", actionInfo, moduleStepVo.actionInfo)
end

