function UISystemGuidePreBehavior:Clear()
    if self.oldEasyTouchEnabled ~= nil then
        EasyTouch.SetEnabled(self.oldEasyTouchEnabled)
        self.oldEasyTouchEnabled = nil
    end
    self._guidePreBehaviorGroups = nil
    
end

function UISystemGuidePreBehavior:SkipClear()
    local guidePreBehaviorGroups = self._guidePreBehaviorGroups
    if guidePreBehaviorGroups == nil then return end
    
    ---由于没有支持 子树 这里只能单阶段修正
    for i, guidePreBehaviorGroup in ipairs(guidePreBehaviorGroups) do
        local preBehaviorType, preBehaviorTypeParams, exParams, exParams1, exParams2 = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level2, guidePreBehaviorGroup))
        preBehaviorType = checkNumber(preBehaviorType)
        if preBehaviorType == GuidePreBehaviorType.CustomEvent then
            printInfo("guide---------------->>>> 反转事件 %s", preBehaviorTypeParams)
            self:HandleTypeCustomEvent(preBehaviorTypeParams, exParams, true)
        elseif preBehaviorType == GuidePreBehaviorType.SetEnabledComponent then
            self:HandleTypeSetEnabledComponent(preBehaviorTypeParams, exParams, exParams1, exParams2, true)
        end
    end
    
end

return UISystemGuidePreBehavior